import { test, expect } from '@playwright/test';

test.describe('User Logout - Secure Session Termination', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should log out user and terminate session securely', async ({ page }) => {
    // Navigate to login page
    await page.goto('/login');

    // Verify login form is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Fill in credentials using getByLabel
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('password123');

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify login success message appears
    const successMessage = page.getByText('Logged in successfully');
    await expect(successMessage).toBeVisible();

    // Navigate to dashboard
    await page.goto('/dashboard');

    // Verify dashboard is visible
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();

    // Verify user is logged in
    const userName = page.getByText('User');
    await expect(userName).toBeVisible();

    // Click logout button using getByRole
    const logoutButton = page.getByRole('button', { name: /log out/i });
    await logoutButton.click();

    // Verify logout confirmation message appears
    const logoutConfirmation = page.getByText('Are you sure you want to log out?');
    await expect(logoutConfirmation).toBeVisible();

    // Verify session is terminated by checking user is no longer visible
    await expect(userName).not.toBeVisible();

    // Verify user is redirected to login page
    await expect(page).toHaveURL(/login/);

    // Verify login form is visible again
    await expect(loginForm).toBeVisible();
  });

  test('should handle logout failure and display error message', async ({ page }) => {
    // Navigate to dashboard
    await page.goto('/dashboard');

    // Verify dashboard is visible
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();

    // Click logout button using getByRole
    const logoutButton = page.getByRole('button', { name: /log out/i });
    await logoutButton.click();

    // Verify logout error message appears
    const errorMessage = page.getByText('Logout failed');
    await expect(errorMessage).toBeVisible();

    // Verify user is still logged in
    const userName = page.getByText('User');
    await expect(userName).toBeVisible();

    // Verify login form is still visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Verify user is not redirected to login page
    await expect(page).not.toHaveURL(/login/);
  });
});
